import heapq, itertools
def dij(s):
    L = {s: 0}; done = set(); h = [(0, s)]
    while h:
        d, u = heapq.heappop(h)
        if u in done: continue
        done.add(u)
        for v, w in adj[u]:
            if v not in done and d + w < L.get(v, 1e9):
                L[v] = d + w; heapq.heappush(h, (d + w, v))
    return L
